with scored as (select *, row_number() over (order by started_at desc, id) row_seq from sessions) select s.id, s.customer_id, s.browser, s.started_at, s.row_seq, case when browser rlike '^(Safari|Chrome)$' then 'OTHER_ZONE' when browser rlike '^(Firefox|Edge)$' then 'EXTENDED' else 'GROUP_A' end as browser_zone, (select avg(x.balance) from accounts x where x.customer_id = s.customer_id) as avg_account_balance from scored s order by id desc
